 check(recipient.ActivePack().document["author"]==draft["author"]&&recipient.ActivePack().document["name"]==draft["name"]&&recipient.ActivePack().document["version"]==draft["version"],"independent recipient retains shared attribution");
 auto before=store.ActivePack().document.dump();check(!store.ImportText("{broken").success&&store.ActivePack().document.dump()==before,"failed import preserves active state");
 pack["desktop"][0]["translation"]="Neue Gemeinschaft";pack["version"]="2";check(store.ImportText(pack.dump()).success&&store.Apply(added.packId).success,"new base import preserves local override");check(store.ActivePack().entries.at(desktop->first).text=="Meine Änderung","local value wins after conflicting base update");
 nh::LanguageStore restarted(root);check(restarted.ActiveLocale()=="de"&&restarted.ActivePack().entries.at(desktop->first).text=="Meine Änderung","selection and edits survive restart");
