 auto meta=store.AddLanguage("de","Metadata fixture");auto metaBase=store.ReadPack(meta.packId);metaBase["author"]="Original author";check(store.ImportText(metaBase.dump()).success,"metadata-only base imported");
 auto metaEdit=store.ReadDraft(meta.packId);metaEdit["name"]="Edited name";metaEdit["author"]="";check(store.Apply(meta.packId,metaEdit).success,"metadata-only edits apply without a saved draft");
 auto reopened=restarted.ReadDraft(meta.packId);check(reopened["name"]=="Edited name"&&reopened["author"]=="","editor reload retains metadata-only edits and intentional empty attribution");
 metaBase["version"]="2";metaBase["name"]="Updated base name";check(store.ImportText(metaBase.dump()).success&&restarted.Apply(meta.packId).success&&restarted.ActivePack().document["version"]=="2"&&restarted.ActivePack().document["name"]=="Edited name","unedited metadata follows base updates while explicit edits persist");
 auto metadataExport=root/L"metadata-share.nrlang";check(restarted.ExportPack(meta.packId,metadataExport).success&&recipient.ImportPack(metadataExport).success&&recipient.Apply(meta.packId).success&&recipient.ActivePack().document["name"]=="Edited name"&&recipient.ActivePack().document["version"]=="2","sharing persisted metadata works without a saved draft");
 auto metadataPath=root/L"Languages"/L"Metadata"/(meta.packId+".json");std::ifstream metadataInput(metadataPath);auto validMetadata=nh::Json::parse(metadataInput);metadataInput.close();auto invalidMetadata=validMetadata;invalidMetadata["packId"]="forged";{std::ofstream out(metadataPath);out<<invalidMetadata.dump();}auto activeBeforeInvalid=restarted.ActivePack().document.dump();check(!restarted.Apply(meta.packId).success&&restarted.ActivePack().document.dump()==activeBeforeInvalid,"invalid metadata cannot replace pack identity or active state");{std::ofstream out(metadataPath);out<<validMetadata.dump();}
 auto englishFile=root/L"english.nrlang";check(store.ExportEnglishTemplate(englishFile).success,"complete contextual English template exported");std::ifstream input(exported);auto independent=nh::Json::parse(input);bool invented=false;for(auto surface:{"desktop","in_game"})for(const auto& entry:independent[surface])if(english.contains(entry["id"].get<std::string>())&&entry["translation"]==english.at(entry["id"].get<std::string>()).english)invented=true;check(!invented&&independent["desktop"].size()>=1&&independent["in_game"].size()>=1,"export carries applicable bundled values and omits untranslated English gaps");
 auto second=store.AddLanguage("de","Deutsch 2");check(second.success&&second.packId!=added.packId,"multiple community packs for one locale");check(!store.AddLanguage("../escape","Bad").success,"locale cannot select a filesystem path");
 auto secondFile=root/L"Languages"/L"Packs"/(second.packId+".nrlang");auto foreign=root/L"foreign.nrlang";std::filesystem::copy_file(secondFile,foreign,std::filesystem::copy_options::overwrite_existing);DeleteFileW(secondFile.c_str());check(CreateHardLinkW(secondFile.c_str(),foreign.c_str(),nullptr)!=FALSE,"hardlinked removal fixture created");check(!store.RemovePack(second.packId).success&&std::filesystem::exists(secondFile)&&std::filesystem::exists(foreign),"removal refuses hardlinked data and preserves unrelated file");
 check(store.Apply(added.packId).success&&store.RemovePack(added.packId).success&&store.ActiveLocale()=="en"&&std::filesystem::exists(root/L"Languages"/L"Drafts"/(added.packId+".nrlang")),"active removal falls through to English while retaining draft work");
 check(store.List().size()>=9,"all nine included language choices remain available independently of community files");
 auto includedDraft=store.ReadDraft("included-pl");auto includedEntry=std::find_if(includedDraft["desktop"].begin(),includedDraft["desktop"].end(),[&](const auto& row){auto id=row.at("id").template get<std::string>();return english.at(id).preserve.empty()&&english.at(id).placeholders.empty();});
 auto includedId=includedEntry->at("id").get<std::string>();(*includedEntry)["translation"]="Moja poprawka";check(store.SaveDraft("included-pl",includedDraft).success&&store.Apply("included-pl",includedDraft).success,"included packs support persistent local edits without mutating product data");
 auto includedExport=root/L"included-share.nrlang";check(store.ExportPack("included-pl",includedExport).success,"edited included pack exported independently");auto shared=recipient.ImportPack(includedExport);check(shared.success&&shared.packId!="included-pl"&&recipient.Apply(shared.packId).success&&recipient.ActivePack().entries.at(includedId).text=="Moja poprawka","another user receives included-pack edits through a community identity");
 check(!store.RemovePack("included-pl").success&&!store.ImportText(store.ReadPack("included-pl").dump()).success,"reserved product pack data cannot be replaced or deleted by authored imports");
 auto community=store.AddLanguage("pl","Polski partial");check(community.success&&store.Apply(community.packId).success&&store.ActivePack().entries.contains(includedId),"missing community entry uses the applicable bundled layer before English");
 auto history=store.ReadPack(community.packId);history["desktop"].push_back({{"id","desktop.obsolete.fixture"},{"translation","Original history"},{"revision",0},{"note","Keep history"}});check(store.ImportText(history.dump()).success,"unknown entries imported as editable history");auto historyDraft=store.ReadDraft(community.packId);historyDraft["desktop"][0]["translation"]="Edited history";check(store.SaveDraft(community.packId,historyDraft).success,"obsolete edits saved independently");auto historyFile=root/L"history-share.nrlang";check(store.ExportPack(community.packId,historyFile).success,"obsolete edits exported");std::ifstream historyStream(historyFile);auto historyExport=nh::Json::parse(historyStream);auto old=std::find_if(historyExport["desktop"].begin(),historyExport["desktop"].end(),[](const auto& row){return row.value("id",std::string{})=="desktop.obsolete.fixture";});check(old!=historyExport["desktop"].end()&&old->at("translation")=="Edited history","local obsolete edits win over original history during sharing");
 auto draftOnly=store.AddLanguage("de","Draft update");auto oldBase=store.ReadPack(draftOnly.packId);oldBase["desktop"].push_back({{"id",desktop->first},{"translation","Base one"},{"revision",1}});check(store.ImportText(oldBase.dump()).success,"draft-only base imported");auto savedOnly=store.ReadDraft(draftOnly.packId);savedOnly["desktop"][0]["translation"]="Local saved draft";check(store.SaveDraft(draftOnly.packId,savedOnly).success,"unapplied draft saved");oldBase["desktop"][0]["translation"]="Base two";check(store.ImportText(oldBase.dump()).success&&store.Conflicted(draftOnly.packId,desktop->first),"base updates flag conflicts with saved unapplied drafts");check(store.ReadDraft(draftOnly.packId)["desktop"][0]["translation"]=="Local saved draft","base update preserves unapplied draft value");
 std::ifstream templateInput(englishFile);auto external=nh::Json::parse(templateInput);check(external["locale"]==""&&external["language"]=="","English template has no target locale");external["packId"]="external-partial-template";external["locale"]="de";external["language"]="Deutsch external";for(auto& row:external["desktop"])if(row["id"]==desktop->first)row["translation"]="Extern übersetzt";check(recipient.ImportText(external.dump()).success&&recipient.Apply("external-partial-template").success&&recipient.ActivePack().entries.at(desktop->first).text=="Extern übersetzt","external partial contextual English template imports and applies");
 return failed?1:0;
